package org.eclipse.kura.core.token.jwt.common;

import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.Optional;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;

public final class TokenInspector {

    private static final Gson GSON = new Gson();

    private final String token;
    private final JsonObject header;
    private final JsonObject payload;

    private TokenInspector(final String token, final JsonObject header, final JsonObject payload) {
        this.token = token;
        this.header = header;
        this.payload = payload;
    }

    public static TokenInspector of(final String token) {
        final String[] segments = token.split("\\.", -1);

        if (segments.length != 3) {
            throw new IllegalArgumentException("not a JWT, expected 3 segments but got " + segments.length);
        }

        return new TokenInspector(token, asJsonObject(segments[0]), asJsonObject(segments[1]));
    }

    public String token() {
        return this.token;
    }

    public JsonObject header() {
        return this.header;
    }

    public JsonObject payload() {
        return this.payload;
    }

    public Optional<JsonElement> headerEntry(final String name) {
        return Optional.ofNullable(this.header.get(name));
    }

    public Optional<JsonElement> claim(final String name) {
        return Optional.ofNullable(this.payload.get(name));
    }

    public static String decodeSegment(final String segment) {
        return new String(Base64.getUrlDecoder().decode(segment), StandardCharsets.UTF_8);
    }

    public static String encodeSegment(final String decoded) {
        return Base64.getUrlEncoder().withoutPadding()
                .encodeToString(decoded.getBytes(StandardCharsets.UTF_8));
    }

    private static JsonObject asJsonObject(final String segment) {
        return GSON.fromJson(decodeSegment(segment), JsonObject.class);
    }

}
